	('3224c2df-1d20-4f3f-b1dc-9ed72525d415', 'CREATED', 'CONTROL_DEFINITION', 'e0f709fa-7cef-40b8-a13a-928e49457a2c', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "ACCESS-02_SIC", "active": false, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('9960eee9-ff78-4f2d-bd99-4baa5d0ce122', 'CREATED', 'CONTROL_DEFINITION_VERSION', '14452494-5199-4aaa-a387-2a5c420161ad', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_ACCESS", "objective": "Activities performed by IT members with privileged accesses must be reviewed :\n- For GxP regulated digital solution, the review of activities must be covered as applicable by the audit trail review\n- For SOX & CSRD regulated digital solution, activities of IT accounts with extended rights (e.g. Firefighters, Privileged accounts) which can have impacts on SOX/CSRD data must be reviewed and documented at least annually.", "ownerTeam": "CYBER_SECURITY", "statement": "Activities Review for privileged accesses", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "e0f709fa-7cef-40b8-a13a-928e49457a2c", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. GQCMS-QU-STD-0000452-User Access Management Controls: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/867621\n2. DFC-QU-STD-0000298-Access Control: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/581828\n3. DIG-CO-SOP-0015241-SAP Security Baseline: https://opella-connect.veevavault.com/ui/#permalink=V190000000JN001\n4. DFC-QU-SOP-0087024-Business Application Access Management: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/738198", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "* Audit trail review record/report for GxP-regulated digital solutions, covering activities performed under privileged access\n* Documented review log for SOX/CSRD-regulated solutions, covering extended-rights accounts (e.g. Firefighter, Privileged accounts), performed and evidenced at least annually* Reviewer sign-off/approval confirming the review was completed (name, date, scope covered)\n* Record of any anomalies or inappropriate activity identified during the review, with follow-up/remediation evidence\n* List of in-scope privileged/extended-rights accounts at the time of review, to confirm completeness of coverage", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n \n -Is a review of activities performed with IT privileged accesses conducted and documented for GxP, SOX and CSRD digital solutions?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('9c3a917f-4b5b-417f-a446-bff280f329fa', 'CREATED', 'CONTROL_DEFINITION', '2104e2f6-3797-4c58-bb62-a72471844a0b', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "B&R-01_SIC", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('e5ed9cc7-020a-4257-a8b6-e3ad71cc7a0e', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'f59f000c-c51f-43c5-abd2-b5419c9ccfd0', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "DEPLOY", "itProcess": "MANAGE_CONTINUITY", "objective": "Digital solutions must have backup implemented (scheduled, executed and monitored) to meet business needs.", "ownerTeam": "CYBER_SECURITY", "statement": "Backup implementation", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["EXTERNALLY_MANAGED_PLATFORM"], "operator": "IN", "outcomeKey": "PLATFORM_HOSTING"}]}, {"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["LIKE_EXTERNAL"], "operator": "IN", "outcomeKey": "PLATFORM_TYPE"}]}, {"conditions": [{"values": ["WEBSITE"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["FULLY_MANAGED"], "operator": "IN", "outcomeKey": "PLATFORM_TYPE"}]}]}, "definitionId": "2104e2f6-3797-4c58-bb62-a72471844a0b", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DFC-QU-SOP-0086073-Backup and Restore - Infrastructure: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/477883", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Backup requirements describing all the components to be backed up with the required SLA documented and implemented with effective monitoring in place.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\nBack-up set up:\n- Is backup specification documented for the digital solution using the backup specification template?\n- Is the backup configured?\n\nMonitoring and logs:\n- Is the backup monitoring effective and are failures captured?\n- Are the logs traceable and retained for ≥ 6 months?\n\n- For digital solution hosted externally, are back up requirements covered in the contractual clauses with the Third Party?", "autoAttestationRule": {"outcomeKey": "PLATFORM_TYPE", "acceptedValues": ["FULLY_MANAGED"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('2bb20468-4c77-40c9-9f7a-29611647f2e7', 'CREATED', 'CONTROL_DEFINITION', 'f0c18028-3806-4afc-82a5-daa24916dbb9', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "BC-01", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('f508cb5b-bd00-487f-b0ce-a14443672073', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'fb8af605-8634-40d1-8f6b-43f5cc30c761', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "A business continuity management process must be defined (e.g., Business Continuity Plan) at business process level with adequate measures established and tested (including Disaster Recovery strategy activation if applicable) to ensure business operations during digital solution’s unavailability (e.g., disasters). This process must be maintained and regularly reviewed to ensure its effectiveness and accuracy.", "ownerTeam": "CYBER_SECURITY", "statement": "Business Continuity", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "f0c18028-3806-4afc-82a5-daa24916dbb9", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009\n2. QUA-CO-OPE-0093984-Business Continuity Plan for GxP Computerized Systems: https://opella-connect.veevavault.com/ui/#permalink=V190000000EQ023", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Actionable business continuity plan describing how the business activities will be executed in case of digital solution''s unavailability.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n* Is a Business Continuity Plan (BCP) defined at the business process level for this digital solution?\n* Does the BCP describe adequate measure to sustain business activities during the solutions'' unavailability (e.g. manual workarounds, alternate processes)?\n* For applicable solutions: does the BCP include Disaster Recovery strategy activation steps?\n* Is the BCP reviewed and updated on a regular cadence to ensure it remains accurate and effective (e.g. after solution changes, org changes, or prior test findings)?\n* Is the BCP readily accessible to the people who would need to execute it during an actual disruption?\n* Any digital solution without a maintained, tested BCP - or with a BCP that hasn''t been reviewed within its required cycle - should be treated as non-complaint.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('ed6d37c6-16ee-4676-ab2b-7e67b1818e80', 'CREATED', 'CONTROL_DEFINITION', '60555ffb-74b5-4d16-aa4a-b6bf56e781f7', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "BC-02", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('354a935e-5b11-409f-97e8-d53d6c4b5d10', 'CREATED', 'CONTROL_DEFINITION_VERSION', '448fecf9-a293-4a1f-9c34-d63f1536f0ba', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Ensure business continuity can be maintained when the digital solution becomes unavailable.", "ownerTeam": "CYBER_SECURITY", "statement": "Alternate Procedures and Continuity Measures", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "60555ffb-74b5-4d16-aa4a-b6bf56e781f7", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Documented alternate procedures\nBusiness Continuity Plan\nWork instructions\nTraining material\nExercise or test results\nEvidence of periodic review and update\nCorrective actions arising from continuity exercises", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\nDocumentation\nAre alternative procedures documented for the affected business activities?\nAre the procedures sufficiently detailed for users to execute them without relying on undocumented knowledge?\nAre roles and responsibilities clearly defined?\nAvailability\nAre the documented procedures available to the personnel who would need to execute them during a disruption?\nCan the procedures be accessed if the digital solution is unavailable?\nTraining\nHave relevant personnel been trained on the alternative procedures?\nIs training evidence available?\nTesting\nHave the alternative procedures been exercised, tested, or used in practice?\nWere the exercises documented?\nWere lessons learned captured?\nMaintenance\nHave the procedures been reviewed within the defined review cycle?\nHave changes in processes, systems, suppliers, or organization been reflected in the procedures?\nEffectiveness\nWould the alternative procedures allow the business activity to continue for the expected disruption period?\nAre there significant manual dependencies or bottlenecks that could prevent successful execution?\nWere any issues identified during testing remediated and tracked to closure?\n\nNon-Compliance Indicators\n\nThe control should be considered non-compliant when:\n\nNo alternative procedure exists.\nProcedures are undocumented.\nProcedures have never been tested.\nPersonnel are unaware of the procedures.\nProcedures are outdated or no longer applicable.\nSignificant deficiencies identified during testing remain unresolved.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('07016d12-ee36-4c4c-9b83-24e479e8dc79', 'CREATED', 'CONTROL_DEFINITION', 'acaad548-9f85-4f40-a483-77773548d0d3', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "RES-01", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('cc9fc14d-d3fc-4588-90a1-2f32dd194b17', 'CREATED', 'CONTROL_DEFINITION_VERSION', '6d622d2c-7035-4308-8673-416d1c75e25f', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Vital digital solutions shall demonstrate through testing and documented evidence that recovery can be completed within the approved Recovery Time Objective.", "ownerTeam": "CYBER_SECURITY", "statement": "Recovery Time Objective Demonstration", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "acaad548-9f85-4f40-a483-77773548d0d3", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Recovery exercise\nRecovery exercise report\nRecovery timings documented: Start time, End time, Measured RTO\nData recovery validated\nDeviations documented and remediated", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\nRecovery Performance\nHas recovery been timed?\nWas recovery completed within the approved RTO (Platinum RTO ≤2; Gold RTO ≤ 4 hours)?\nWas the approved RPO achieved (≤ 15 mins)?\nWere all critical services, data and integrations restored?\nWere all critical services restored?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('0b804c5b-5859-45a4-98ee-d121a9af7a35', 'CREATED', 'CONTROL_DEFINITION', '7203e1eb-1998-4172-9391-7afdb2cc24c0', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "RES-02", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('a48c1684-f9e1-4fea-8140-62b057077344', 'CREATED', 'CONTROL_DEFINITION_VERSION', '3c5e8b8a-d06d-4ea9-ac84-a99f00264815', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Dependencies required for recovery shall be identified, documented, and included in recovery procedures and testing activities.", "ownerTeam": "CYBER_SECURITY", "statement": "Critical Dependency Identification and Recovery Sequencing", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "7203e1eb-1998-4172-9391-7afdb2cc24c0", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Dependency map\nRecovery sequence\nArchitecture documentation", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\nDependency Identification\nHave all business, technical, infrastructure, security, data, identity, network, integration, and third-party dependencies required for operation and recovery of the digital solution been identified?\nAre dependencies documented in architecture diagrams, recovery procedures, or dependency inventories?\nDoes the dependency inventory include both internal and external services?\nSingle Points of Failure\nHave potential single points of failure been identified and assessed?\nHave mitigation measures been implemented, documented, or formally accepted through risk management processes?\nRecovery Sequence\nIs the recovery sequence documented?\nDoes the recovery sequence identify which systems, services, databases, integrations, and infrastructure components must be recovered first?\nIs the recovery order consistent with the documented recovery procedures?\nRecovery Objectives\nAre dependency recovery objectives aligned with the digital solution''s Recovery Time Objective (RTO) and Recovery Point Objective (RPO)?\nCould any dependency prevent achievement of the approved recovery objectives?\nThird-Party Dependencies\nFor externally provided services, are supplier recovery responsibilities documented?\nHas the supplier demonstrated recovery capability through testing, assurance reports, or contractual commitments?\nEvidence Quality\nIs there evidence that dependency information has been reviewed and updated following significant architecture, supplier, or infrastructure changes?\nNon-Compliance Indicators\n\nThe control should be considered non-compliant if:\n\nCritical dependencies are unknown or undocumented.\nRecovery sequencing is not defined.\nDependency recovery objectives exceed the solution''s approved RTO or RPO.\nSingle points of failure have not been assessed.\nRecovery relies on undocumented supplier capabilities.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('629b409b-17c8-4715-8546-ee2f02567bba', 'CREATED', 'CONTROL_DEFINITION', 'e6316cd5-533d-41f7-b614-fadf39919e61', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "RES-03", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('281c2d63-70f6-4ef5-90e6-083fcf4dd4f2', 'CREATED', 'CONTROL_DEFINITION_VERSION', '474f8d0a-4e96-4eaf-878a-9eb61ff7e593', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Ensure recovery objectives and recovery capabilities are defined, implemented, tested, and aligned with the assigned Recovery Tier and Business Criticality classification of the digital solution.", "ownerTeam": "CYBER_SECURITY", "statement": "Vital Application Recovery Readiness Review", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "e6316cd5-533d-41f7-b614-fadf39919e61", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Annual review report\nAction tracking\nUpdated DR documentation", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\nRecovery Asset Protection\nAre recovery assets identified and documented?\nDo recovery assets include backups, configurations, infrastructure definitions, application components, scripts, documentation, recovery credentials, and recovery environments where applicable?\nAre recovery assets protected from unauthorized modification or deletion?\nRecovery Environment\nIs a recovery environment available and documented?\nCan recovery activities be executed independently from a compromised production environment?\nAre recovery procedures clearly documented?\nRecovery Credentials\nAre recovery accounts and credentials protected and managed appropriately?\nCan recovery activities still be performed if production privileged accounts are unavailable or compromised?\nRecovery Integrity\nAre processes defined to verify the integrity and validity of recovered systems, data, and configurations?\nDoes the recovery process include validation activities before restored services are returned to operation?\nTesting and Validation\nHas the recovery design been tested?\nDo test results demonstrate successful recovery of the required components?\nWere recovery issues identified during testing tracked and remediated?\nRecovery Objective Achievement\nDoes available evidence demonstrate that the cyber recovery design can support the approved Recovery Time Objective (RTO) and Recovery Point Objective (RPO)?\nFor Vital applications, does the design demonstrate capability to support Platinum recovery requirements?\nThird-Party Recovery\nFor externally hosted or supplier-supported solutions, has evidence been reviewed demonstrating the supplier''s ability to support recovery requirements?\nAre responsibilities clearly documented through a Shared Responsibility Model?\n\nCompliance Indicators\nPass\nRecovery Tier assigned.\nRTO and RPO defined.\nRecovery capability documented.\nRecovery capability tested or validated.\nNo material open recovery gaps.\n\nConditional Pass\nRecovery capability exists.\nMinor documentation, testing, or remediation gaps remain.\nDefined action plan exists.\n\nFail\nRecovery Tier not assigned.\nRecovery objectives undefined.\nRecovery capability not documented.\nNo evidence of recovery validation.\nMaterial recovery gaps remain unmanaged.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('28b4f709-6e89-4107-97b3-15073e3f707a', 'CREATED', 'CONTROL_DEFINITION', 'b26f5d0e-36e4-41af-8852-222d0a1e0e58', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "RES-04", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('6303c45e-99f0-44af-bf53-6364b025b19b', 'CREATED', 'CONTROL_DEFINITION_VERSION', '4cd17122-6b13-4d72-a56d-f53e420d173f', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Ensure the digital solution can demonstrably recover within approved recovery objectives and that recovery capabilities remain effective throughout the solution lifecycle.", "ownerTeam": "CYBER_SECURITY", "statement": "Recovery Objective Validation", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "b26f5d0e-36e4-41af-8852-222d0a1e0e58", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Recovery test reports\nDisaster Recovery exercise reports\nMeasured recovery duration\nMeasured data recovery point\nRecovery validation evidence\nRecovery improvement actions\nTest result approvals\nSupplier recovery testing evidence (where applicable)", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\nRecovery Testing\nHas a recovery exercise been performed?\nWas the recovery exercise completed using documented recovery procedures?\nWas the exercise representative of the recovery scenario being evaluated?\nRecovery Time Objective (RTO)\nWas the actual recovery duration measured?\nDid the digital solution achieve the approved Recovery Time Objective?\nIf the approved RTO was not achieved, was a remediation plan documented?\nRecovery Point Objective (RPO)\nWas the actual data recovery point measured?\nDid the digital solution achieve the approved Recovery Point Objective?\nWas any data loss within the approved tolerance?\nRecovery Scope\nWere all critical solution components recovered?\nWere critical data, configurations, interfaces, integrations, and supporting services included in the recovery validation?\nWere dependencies recovered and operational?\nBusiness Validation\nWas business functionality validated following recovery?\nWere business users involved where appropriate?\nWas the recovered solution demonstrated to be fit for use?\nRemediation and Continuous Improvement\nWere recovery issues, delays, or failures documented?\nWere corrective actions assigned and tracked?\nHas evidence of remediation been reviewed when required?\nThird-Party Recovery\n\nFor supplier-supported solutions:\n\nHas supplier recovery evidence been reviewed?\nHas the supplier demonstrated recovery capability consistent with contractual commitments?\nAre supplier recovery responsibilities clearly documented?\nNon-Compliance Indicators\n\nThis control should be considered non-compliant if:\n\nRecovery exercises have not been performed.\nRecovery objectives cannot be demonstrated.\nRecovery time was not measured.\nRecovery point was not measured.\nRecovery exceeded approved objectives without remediation.\nCritical components were not included in testing.\nRecovery evidence is unavailable.\nSupplier recovery capabilities cannot be demonstrated where applicable.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('7279f541-6306-46db-9339-9df724dcc6e1', 'CREATED', 'CONTROL_DEFINITION', '0b57cdbe-bf41-4c48-9366-ab632a50a16e', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DP-01", "active": false, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('be7cb601-4908-4958-b7fc-c2f3f80015b3', 'CREATED', 'CONTROL_DEFINITION_VERSION', '3e455904-0d85-485a-85e3-5d53d94951ef', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "PLAN", "itProcess": "MANAGE_RISK", "objective": "The digital solution must undergo a privacy Data Asset Assessment (DAA) to evaluate compliance with privacy requirements.", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "Execute Personal Data Privacy Assessment", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "0b57cdbe-bf41-4c48-9366-ab632a50a16e", "reviewerTeam": "DATA_PRIVACY", "sourceOfTruth": "1. EBI-CO-STD-0000410-Opella Data Privacy Standard (v1.0)\nhttps://opella-connect.veevavault.com/ui/#permalink=V190000000KB037\n\n2. Privacy Hub\nhttps://sanofi.sharepoint.com/sites/opella-compliance-site/SitePages/Work-with-personal-data-v1.0.aspx?CT=1736934649051&OR=OWA-NT-Mail&CID=47d9fdb6-098e-ddca-947b-ad4f41eab8f3", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Personal Data Privacy Assessment documented in OneTrust.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": true, "attestationGuidance": "1. The digital solution is inventoried as \"digital asset\" in the Opella Privacy Care (One Trust) asset inventory\n2. A Digital Asset Assessment exists and it is either in status \"Completed\" or \"Completed with open risks\"\n3. If the Digital Asset Assessment is \"completed with open risks\", all the risks must be in a status different from \"Ongoing mitigation\" (Avoided, Reduced, Accepted, Expired or Materialized)", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('c875fd54-733b-4ffc-b186-6f1c41c9083a', 'CREATED', 'CONTROL_DEFINITION', 'bc4c5ba4-4725-4803-a805-b6b0d63c7955', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DP_RISK-2", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('d4be3757-6294-4318-b988-94090ff1f299', 'CREATED', 'CONTROL_DEFINITION_VERSION', '1f9922c6-2922-4792-a88e-22138bc07707', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "PLAN", "itProcess": "MANAGE_RISK", "objective": "The owner of the digital solution must self attest compliance with a list of requirements, depending on the type of the digital solution", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "Privacy Compliance Declaration", "triggerRule": null, "definitionId": "bc4c5ba4-4725-4803-a805-b6b0d63c7955", "reviewerTeam": "DATA_PRIVACY", "sourceOfTruth": "1. EBI-CO-STD-0000410-Opella Data Privacy Standard (v1.0)\nhttps://opella-connect.veevavault.com/ui/#permalink=V190000000KB037\n\n2. Privacy Hub\nhttps://sanofi.sharepoint.com/sites/opella-compliance-site/SitePages/Work-with-personal-data-v1.0.aspx?CT=1736934649051&OR=OWA-NT-Mail&CID=47d9fdb6-098e-ddca-947b-ad4f41eab8f4", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": false, "targetedEvidence": "Privacy Compliance declaration in the risk profiling tool", "applicabilityType": "ALWAYS", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": true, "attestationGuidance": "The owner of the Digital Property must self-attest compliance with certain requirements depending on the digital property type, as a mandatory pre-condition for go-live approval\n\nFor all Digital Solutions, this will be captured in OneTrust when the Digital Assessment is performed.", "autoAttestationRule": null, "assessmentTemplateKey": "DATA_PRIVACY_SELF_ASSESSMENT_V1", "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('ec386ec0-a8a5-437f-b977-2503c7e6f372', 'CREATED', 'CONTROL_DEFINITION', 'dc778f3e-fddd-45a6-a215-8b3873291fc9', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DEL-02", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('ca0a1ca8-fd4d-4816-b01e-d397e3c2d350', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'a801078c-49ce-4171-86d3-9a8b1f7fc4d2', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The digital solution must have a defined set of requirements that describe the functional (i.e., business-process related) and non-functional (e.g., Audit Trail, Electronic Record, Electronic Signature, Data Privacy, Cybersecurity) needs to satisfy the business. All requirements must be specific, measurable, achievable, realistic and testable (SMART).", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Gather Requirements", "triggerRule": null, "definitionId": "dc778f3e-fddd-45a6-a215-8b3873291fc9", "reviewerTeam": "PRODUCT_PROJECT_DELIVERY", "sourceOfTruth": "DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "The requirements the digital solution must meet, including the list of requirements supporting the business process, as well as the applicable non functional requirements.\nE.g.: Epic and user stories in Jira, Requirements in HP ALM, Requirement document in Connect CMS...", "applicabilityType": "ALWAYS", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n* Are both functional (business-process related) and non-functional requirements (e.g. Audit Trail, Electronic Record, Electronic Signature, Data Privacy, Cybersecurity) documented for the digital solution?\n* Is each requirement specific, measurable, achievable, realistic, and testable (SMART)?\n* Are requirements captured and traceable in the appropriate tool for the solution (e.g. Epics/user stories in JIRA, requirements in HP ALM, requirement document in Connect CMS)?\n* Is there evidence requirements were reviewed/approved by the appropriate business and IT stakeholders before design/build began?\n* Are requirements complete relative to the business process being supported, with no material gaps identified later in the lifecycle?\n* Any digital solution where requirements are missing, non-SMART, or not traceable to a recognized system of record should be treated as noncompliant", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('af47463e-5cc4-421b-bac4-b281069090b2', 'CREATED', 'CONTROL_DEFINITION', '400a30b8-63fb-4ba6-b3fa-f4ad3d5c3ad7', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DEL-10", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('3e558639-9314-40e8-8404-febed53ce94c', 'CREATED', 'CONTROL_DEFINITION_VERSION', '4a5f315a-c55f-411d-99ff-7d3feb30161b', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The digital solution must have traceability by linking requirements to its specifications and testing artifacts.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Ensure Traceability", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "400a30b8-63fb-4ba6-b3fa-f4ad3d5c3ad7", "reviewerTeam": "PRODUCT_PROJECT_DELIVERY", "sourceOfTruth": "DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Matrix demonstrating traceability between the requirements, specifications and tests.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following: \n\n* Is a traceability matrix in place linking each requirement to its corresponding specification(s)?\n* Does the matrix also link each requirement/specification to its corresponding test artifact (test case/script)?\n* Is coverage complete - i.e. can every requirement be traced through to a specification and a test, with no orphaned requirements or untested specifications?\n* Is the traceability matrix kept current as requirements, specifications, or test artifacts change throughout the lifecycle?\n* Can the matrix be used to demonstrate full lifecycle coverage during an audit or inspection (particularly for GxP solutions)?\n* Any digital solution where requirements cannot be traced end-to-end to specifications and tests should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('230d0273-71b1-4790-94b8-f702b0d11083', 'CREATED', 'CONTROL_DEFINITION', '287cf554-c729-412c-ae17-d2000c267ffb', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DEL-13_SIC", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('b665d510-512b-4713-84ec-f7f0977504ec', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'ac28c5c5-9294-40b4-a232-f0e8f0672064', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "DEPLOY", "itProcess": "MANAGE_DELIVERY", "objective": "A summary of controls execution (as per the defined control strategy) must be documented to authorize the usage of the digital solution. Deviations from the controls strategy must be justified. For unresolved deviations, actions plans must be recorded to monitor their resolutions until closure.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Authorize for Use", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "287cf554-c729-412c-ae17-d2000c267ffb", "reviewerTeam": "PRODUCT_PROJECT_DELIVERY", "sourceOfTruth": "DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Summary of the Control/Validation Strategy execution, including at least:\n - all the applicable controls and their achievement''s details\n - deviations from the strategy with associated justification and action plan to remediate them\n- the readiness status of the operational & maintenance processes\n- decision to authorize the usage of the digital solution\nE.g.: Authorization for use, Release report", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n- Has a summary of controls executed been documented?\n- Are all controls defined in the control strategy implemented? If not, are deviations justified?\n- For any unresolved deviations, is there an action plan defined with an assigned owner and due date?\n- Based on their impact, are there any unresolved deviation that would block the authorization for use?\n- Have operational readiness activities been properly executed to ensure the digital solution is ready for operation?\n- Has a comprehensive review of control execution, deviations, and operational readiness been conducted to make an informed decision on authorizing the usage of the digital solution?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('f6eea1cb-5572-4009-840d-169cb34dba1e', 'CREATED', 'CONTROL_DEFINITION', 'd692204e-c688-4594-bf06-dddfaf4105ae', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DEL-14", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('da7a5dcb-c54a-454e-b7ed-86d84ce0c111', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'fa3a3f95-3970-4c90-a3a5-61dfb20e8b15', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The digital solution identified as digital property must adhere to the Digital Properties process.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Execute Digital Properties Process", "triggerRule": null, "definitionId": "d692204e-c688-4594-bf06-dddfaf4105ae", "reviewerTeam": null, "sourceOfTruth": "DFC-QU-GOP-0000613-Life Cycle Management of Digital Properties: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/860315", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": false, "targetedEvidence": "Reference of the digital solution recorded in Digital Property Registry.", "applicabilityType": "ALWAYS", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": true, "attestationGuidance": "Reference of the digital solution recorded in Digital Property Registry.", "autoAttestationRule": {"outcomeKey": "PROPERTY_TYPE", "acceptedValues": ["WEBSITE", "SOCIAL", "MOBILE_APP", "CHATBOT"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
	('180ff4b5-cb26-45f5-b5fc-ccd509a2b004', 'CREATED', 'CONTROL_DEFINITION', 'fddc9578-6e8f-4c98-92a3-fdd6c51a1ce5', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DEL-15", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-10-20 00:00:00', 'USER'),
