	('0227a849-b677-44a3-ae34-0ec5a9fe6409', 'CREATED', 'CONTROL_DEFINITION_VERSION', '8d9a55a5-3065-4c99-b3c4-d4608c949797', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The AI solution shall have documented intended purpose, architecture, limitations, risks and usage instructions.", "ownerTeam": "DIGITAL_DATA", "statement": "AI Documentation", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "062d0594-84cf-4772-8628-3a89ed425805", "reviewerTeam": "AI", "sourceOfTruth": "https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "AI Solution Documentation, Architecture Diagram", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "Is the intended purpose of the AI solution documented? Are the architecture, AI models, data sources, knowledge sources, and integrations documented? Are the known limitations, assumptions, and risks documented? Are user instructions and operating procedures available? Is documentation maintained throughout the solution lifecycle?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
