	('99a9fada-dc93-4de9-a1a2-ae527afd4234', 'CREATED', 'CONTROL_DEFINITION_VERSION', '8106b39b-65b6-4f65-816d-812daa068203', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "Human oversight mechanisms shall be documented and implemented when required by the AI risk classification.", "ownerTeam": "DIGITAL_DATA", "statement": "AI Human Oversight Design", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "892f2f7f-fc52-4505-971d-b987d23d5792", "reviewerTeam": "AI", "sourceOfTruth": "https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Design Documentation, User Procedures", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "Are human oversight mechanisms defined and documented? Can users intervene, challenge, approve, or override AI outputs when required? Are roles and responsibilities for oversight clearly defined? Is evidence of human approval or review retained where applicable?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
