	('37a96547-47ff-4a08-ac2d-e5b0536d8d87', 'CREATED', 'CONTROL_DEFINITION_VERSION', '25ad077b-c74b-474f-b953-2d55d6e61625', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_DELIVERY", "objective": "ONLY applicable if there is 2 way communication on the platform:\nIf monitoring is performed by an outsourced service provider, a PV clause must be included in the contract wherever a service provider is involved in monitoring. \n\nNote: If this is performed by Opella employee, this control is not required.", "ownerTeam": "PV", "statement": "PV Monitoring for Digital Properties - PV Clause availability in Contract", "triggerRule": {"groups": [{"conditions": [{"values": ["PV"], "operator": "IN", "outcomeKey": "PV"}, {"values": ["SERVICE_PROVIDER"], "operator": "IN", "outcomeKey": "PV_MONITOR"}]}]}, "definitionId": "6d4c5094-f7dd-4536-9dfc-17f0c7346e6b", "reviewerTeam": "PV", "sourceOfTruth": "DFC-QU-GOP-0000613-Life Cycle Management of Digital Properties", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Before GO LIVE: Signed contract containing PV clause, for any digital property involving a service provider", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n1. Does the digital property has two-way communication where PV information may be mentioned?\n2. Who is responsible to perform the monitoring (Service provider or Opella employee)?\n3. If a service provider performs the monitoring, is a PV clause present in the contract?\n4. If Opella employee, no action is required for this control", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-10-20 00:00:00', 'USER'),
