	('edbc0a30-0a32-48fd-9181-278e63cde1c6', 'CREATED', 'NFR_DEFINITION_VERSION', '29c6c463-05a5-478f-a163-1b70af516441', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The solution shall support monitoring of AI quality, reliability, and performance. Performance thresholds and monitoring metrics shall be defined. Mechanisms shall exist to detect degradation of AI performance over time. Monitoring results shall be periodically reviewed.", "ownerTeam": "DIGITAL_DATA", "statement": "The solution shall support monitoring of AI performance, quality, and reliability over time.", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "23b2e61f-a06c-44b1-89fc-ca0736cb8d0c", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-20 00:00:00', 'USER'),
